        self.namespace['MA'] = 1_000_000.0
        self.namespace['MegaAmp'] = 1_000_000.0
        self.namespace['megaamp'] = 1_000_000.0
        self.namespace['mA'] = 1e-3
        self.namespace['uA'] = 1e-6
        self.namespace['μA'] = 1e-6
        self.namespace['W'] = 1.0
        self.namespace['mW'] = 1e-3
        self.namespace['uW'] = 1e-6
        self.namespace['μW'] = 1e-6
        self.namespace['kW'] = 1_000.0
        self.namespace['MW'] = 1_000_000.0
        self.namespace['MegaWatt'] = 1_000_000.0
        self.namespace['megawatt'] = 1_000_000.0

    def _cmd_plot(self, *args, **kwargs):
        """Handle inline plot(expr, (x, min, max)) calls."""
        if not args:
            raise ValueError("plot() requires at least one expression or function.")

        expr = args[0]
        var = None
        x_min = -10.0
        x_max = 10.0
        title = kwargs.get('title', '')

        # Check if second arg is a tuple (x, min, max)
        if len(args) > 1 and isinstance(args[1], (tuple, list)):
            range_info = args[1]
            if len(range_info) >= 3:
                var = range_info[0]
                x_min = float(sp.sympify(range_info[1]).evalf())
                x_max = float(sp.sympify(range_info[2]).evalf())
            elif len(range_info) == 2:
                x_min = float(sp.sympify(range_info[0]).evalf())
                x_max = float(sp.sympify(range_info[1]).evalf())

        # Check if parametric: plot([x(t), y(t)], (t, min, max))
        if isinstance(expr, (list, tuple)) and len(expr) == 2 and str(var) == 't':
            return PlotEngine.generate_parametric_plot(expr[0], expr[1], t_symbol=var, t_min=x_min, t_max=x_max, title=title)

        # Check if polar: plot(r(theta), (theta, min, max))
        if str(var) in ('theta', 'θ') or kwargs.get('coords') == 'polar':
            return PlotEngine.generate_polar_plot(expr, theta_symbol=var, theta_min=x_min, theta_max=x_max, title=title)

        return PlotEngine.generate_plot(expr, var=var, x_min=x_min, x_max=x_max, title=title)

    def _cmd_plot_parametric(self, expr_x, expr_y, range_tuple=None, title=''):
        t_var = sp.Symbol('t')
        t_min = -10.0
        t_max = 10.0
        if range_tuple and isinstance(range_tuple, (tuple, list)) and len(range_tuple) >= 3:
            t_var = range_tuple[0]
            t_min = float(sp.sympify(range_tuple[1]).evalf())
            t_max = float(sp.sympify(range_tuple[2]).evalf())
        return PlotEngine.generate_parametric_plot(expr_x, expr_y, t_symbol=t_var, t_min=t_min, t_max=t_max, title=title)

    def _cmd_plot_polar(self, expr_r, range_tuple=None, title=''):
        th_var = sp.Symbol('theta')
        th_min = 0.0
        th_max = 2 * np.pi
        if range_tuple and isinstance(range_tuple, (tuple, list)) and len(range_tuple) >= 3:
            th_var = range_tuple[0]
            th_min = float(sp.sympify(range_tuple[1]).evalf())
            th_max = float(sp.sympify(range_tuple[2]).evalf())
        return PlotEngine.generate_polar_plot(expr_r, theta_symbol=th_var, theta_min=th_min, theta_max=th_max, title=title)

    def _cmd_plot3d(self, *args, **kwargs):
        """Handle plot3d(f(x, y), x=a..b, y=c..d) calls."""
        if not args:
            raise ValueError("plot3d() requires an expression or function of two variables.")
        expr = args[0]
        x_range = args[1] if len(args) > 1 else None
        y_range = args[2] if len(args) > 2 else None
        title = kwargs.get('title', '')
        return PlotEngine.generate_3d_plot(expr, x_range=x_range, y_range=y_range, title=title)

    def _cmd_polygon_omraade(self, *args, **kwargs):
        """
        polygonOmråde(Uligheder, x = a..b, y = c..d)
        Generates linear inequality feasible polygon plot.
        """
        ineqs = args[0] if args else self.namespace.get('Uligheder', [])
        x_min, x_max = -1.0, 13.0
        y_min, y_max = -1.0, 12.0
        x_var, y_var = 'x', 'y'

        for arg in args[1:]:
            if isinstance(arg, (tuple, list)):
                if len(arg) >= 3:
                    v_name = str(arg[0])
                    v_min = float(sp.sympify(arg[1]).evalf())
                    v_max = float(sp.sympify(arg[2]).evalf())
                    if v_name == 'y':
                        y_var = v_name
                        y_min, y_max = v_min, v_max
                    else:
                        x_var = v_name
                        x_min, x_max = v_min, v_max
                elif len(arg) == 2:
                    x_min = float(sp.sympify(arg[0]).evalf())
                    x_max = float(sp.sympify(arg[1]).evalf())

        return PlotEngine.generate_polygon_area_plot(
            inequalities=ineqs,
            x_min=x_min, x_max=x_max,
            y_min=y_min, y_max=y_max,
            x_var=x_var, y_var=y_var
        )

    def _cmd_lp_plot(self, *args, **kwargs):
        """
        LPplot(f(x, y), Uligheder, N)
        Plots objective function level curves over the feasible polygon region.
        """
        if not args:
            raise ValueError("LPplot requires an objective function.")
        obj = args[0]
        ineqs = args[1] if len(args) > 1 else self.namespace.get('Uligheder', [])
        levels = args[2] if len(args) > 2 else [0, 120, 300]
        return PlotEngine.generate_polygon_area_plot(
            inequalities=ineqs,
            x_min=-1.0, x_max=13.0,
            y_min=-1.0, y_max=12.0,
            objective=obj,
            level_curves=levels
        )

    def reset(self):
        """Reset workspace and variables to default state."""
        self._init_builtins()
        self._initial_namespace = dict(self.namespace)
        self._builtin_keys = set(self.namespace.keys())
        self.history.clear()
        self.history_raw.clear()
        self.execution_count = 0

    def get_variables(self) -> dict:
        """Return user-defined symbols and functions."""
        user_vars = {}
        for k, v in self.namespace.items():
            if k.startswith('_') or k.startswith('Out_') or k == 'ans':
                continue
            if k not in self._builtin_keys:
                user_vars[k] = v
            elif k in self._initial_namespace and v != self._initial_namespace[k]:
                user_vars[k] = v
        return user_vars

    @staticmethod
    def split_statements(text: str) -> list[str]:
        statements = []
        current = []
        depth = 0
        for ch in text:
            if ch in '([{':
                depth += 1
                current.append(ch)
            elif ch in ')]}':
                depth = max(0, depth - 1)
                current.append(ch)
            elif ch in ('\n', ';') and depth == 0:
                stmt = "".join(current).strip()
                if stmt:
                    statements.append(stmt)
                current = []
            else:
                current.append(ch)
        if current:
            stmt = "".join(current).strip()
            if stmt:
                statements.append(stmt)
        return statements

    @staticmethod
    def _make_subscript_alias(var_name: str) -> str:
        _SUB_MAP = {
            '0': '₀', '1': '₁', '2': '₂', '3': '₃', '4': '₄',
            '5': '₅', '6': '₆', '7': '₇', '8': '₈', '9': '₉',
            'a': 'ₐ', 'b': 'ᵦ', 'e': 'ₑ', 'h': 'ₕ', 'i': 'ᵢ', 'j': 'ⱼ',
            'k': 'ₖ', 'l': 'ₗ', 'm': 'ₘ', 'n': 'ₙ', 'o': 'ₒ',
            'p': 'ₚ', 'r': 'ᵣ', 'u': 'ᵤ', 'v': 'ᵥ', 'x': 'ₓ',
            's': 'ₛ', 't': 'ₜ',
        }
        _REV_SUB_MAP = {v: k for k, v in _SUB_MAP.items()}
        if '_' in var_name:
            parts = var_name.split('_', 1)
            if all(c in _SUB_MAP for c in parts[1]):
                return parts[0] + ''.join(_SUB_MAP[c] for c in parts[1])
        elif any(c in _REV_SUB_MAP for c in var_name):
            rev_chars = "".join(_REV_SUB_MAP.keys())
            return re.sub(rf'(?<=[a-zA-Z_])([{re.escape(rev_chars)}]+)',
                          lambda m: '_' + ''.join(_REV_SUB_MAP.get(c, c) for c in m.group(1)), var_name)
        return ""

    def evaluate(self, input_str: str, precision: int = 6) -> CASResult:
        """
        Evaluate a mathematical expression or CAS command.
        Returns a CASResult object.
        """
        statements = self.split_statements(input_str)
        if len(statements) > 1:
            last_res = None
            for stmt in statements:
                last_res = self.evaluate(stmt, precision=precision)
            return last_res

        start_time = time.perf_counter()
        self.execution_count += 1
        exec_idx = self.execution_count

        # Parse the input
        parse_res: ParseResult = MathParser.parse(input_str, local_dict=self.namespace)

        if parse_res.is_command:
            if parse_res.command_name == 'reset':
                self.reset()
                elapsed = (time.perf_counter() - start_time) * 1000
                res = MathFormatter.format_all("Workspace reset successfully.", elapsed, precision)
                return res
            elif parse_res.command_name == 'whos':
                uv = self.get_variables()
                var_desc = ", ".join(f"{k} = {v}" for k, v in uv.items()) if uv else "No user variables defined."
                elapsed = (time.perf_counter() - start_time) * 1000
                res = MathFormatter.format_all(var_desc, elapsed, precision)
                return res
            elif parse_res.command_name == 'help':
                topic = parse_res.command_args[0] if parse_res.command_args else ""
                help_texts = {
                    "polygonOmråde": "polygonOmråde(Uligheder, x = a .. b, y = c .. d)\nPlots the feasible polygon region bounded by linear inequalities with boundary equation labels.",
                    "polygonOmraade": "polygonOmråde(Uligheder, x = a .. b, y = c .. d)\nPlots the feasible polygon region bounded by linear inequalities with boundary equation labels.",
                    "LPplot": "LPplot(f(x, y), Uligheder, N)\nPlots objective function level curves over a linear inequality feasible region.",
                    "to_bin": "to_bin(val, bits=8)\nFormat integer as fixed-width binary nibbles (e.g. 0b0101 1010).",
                    "to_hex": "to_hex(val, bits=8)\nFormat integer as hexadecimal string (e.g. 0x5A).",
                    "twos_comp": "twos_comp(val, bits=8)\nCalculate signed value from two's complement or vice versa.",
                    "two_comp": "two_comp(val, bits=8)\nCalculate signed value from two's complement or vice versa.",
                    "twos_comp_repr": "twos_comp_repr(val, bits=8)\nCalculate two's complement signed/unsigned breakdown.",
                    "two_comp_repr": "two_comp_repr(val, bits=8)\nCalculate two's complement signed/unsigned breakdown.",
                    "bit_set": "bit_set(val, bit)\nSet specific bit index to 1.",
                    "bit_clear": "bit_clear(val, bit)\nClear specific bit index to 0.",
                    "bit_toggle": "bit_toggle(val, bit)\nToggle specific bit index."
                }
                desc = help_texts.get(topic, f"? {topic}\nHelp: Function '{topic}' is available in the CAS engine.")
                elapsed = (time.perf_counter() - start_time) * 1000
                res = MathFormatter.format_all(desc, elapsed, precision)
                return res
            elif parse_res.command_name == 'with':
                pkg_name = parse_res.command_args[0] if parse_res.command_args else ""
                pkg_funcs = self.load_package(pkg_name)
                elapsed = (time.perf_counter() - start_time) * 1000
                res = MathFormatter.format_all(pkg_funcs, elapsed, precision, suppress_output=parse_res.suppress_output)
                self._update_history(exec_idx, pkg_funcs, res)
                return res
            elif parse_res.command_name == 'unassign':
                unassigned = []
                for name in parse_res.command_args:
                    self.namespace[name] = sp.Symbol(name)
                    unassigned.append(name)
                    alias = self._make_subscript_alias(name)
                    if alias and alias in self.namespace:
                        self.namespace[alias] = sp.Symbol(alias)
                msg = f"Unassigned: {', '.join(unassigned)}" if unassigned else "unassign: specify variable(s)"
                elapsed = (time.perf_counter() - start_time) * 1000
                res = MathFormatter.format_all(msg, elapsed, precision, suppress_output=parse_res.suppress_output)
                return res

        # Handle PlotData directly if result is a plot
        if isinstance(parse_res.sympy_expr, PlotData):
            elapsed = (time.perf_counter() - start_time) * 1000
            res = CASResult(
                raw_result=parse_res.sympy_expr,
                exact_latex=r"\text{Plot Generated}",
                numeric_latex=r"\text{Plot Generated}",
                exact_text="[Plot Object]",
                numeric_text="[Plot Object]",
                python_code=input_str,
                is_numeric_available=False,
                is_plot=True,
                plot_data={'plot_obj': parse_res.sympy_expr},
                result_type="Plot",
                execution_time_ms=elapsed
            )
            self._update_history(exec_idx, parse_res.sympy_expr, res)
            return res

        raw_val = parse_res.sympy_expr

        # Handle Variable/Function Assignment
        if parse_res.is_assignment and parse_res.assign_var:
            var_name = parse_res.assign_var
            if parse_res.assign_args:
                # Function definition: f(x) := expr -> define lambda/function
                args_syms = [sp.Symbol(a) if isinstance(a, str) else a for a in parse_res.assign_args]
                func_expr = raw_val
                # Create callable function in namespace
                def _user_func(*f_args, _expr=func_expr, _syms=args_syms):
                    subs_dict = {sym: arg for sym, arg in zip(_syms, f_args)}
                    return _expr.subs(subs_dict)

                self.namespace[var_name] = _user_func
                raw_val = sp.Eq(sp.Function(var_name)(*args_syms), func_expr)
            else:
                self.namespace[var_name] = raw_val
                sub_alias = self._make_subscript_alias(var_name)
                if sub_alias:
                    self.namespace[sub_alias] = raw_val

        # Update History
        elapsed = (time.perf_counter() - start_time) * 1000
        # Suppress SymPyDeprecationWarning that can fire during sp.latex/simplify when
        # the expression contains non-Expr arguments (Mul/Pow with Tuple) — a known
        # SymPy edge case with implicit_multiplication_application transformer.
        with warnings.catch_warnings():
            warnings.filterwarnings('ignore', category=SymPyDeprecationWarning)
            warnings.filterwarnings('ignore', message='.*non-Expr.*')
            formatted_res = MathFormatter.format_all(raw_val, elapsed, precision, suppress_output=parse_res.suppress_output)

        # Check if the command was solve(...) or fsolve(...) to format the solution clearly (e.g. x = 4)
        clean_in = input_str.strip()
        if (clean_in.startswith('solve(') or clean_in.startswith('fsolve(')) and not parse_res.is_assignment:
            var_name = None
            var_match = re.search(r',\s*([a-zA-Z_][a-zA-Z0-9_]*)\s*\)$', clean_in)
            if var_match:
                var_name = var_match.group(1)
            else:
                inner_match = re.match(r'^(?:solve|fsolve)\s*\((.*)\)$', clean_in, re.DOTALL)
                if inner_match:
                    inner_txt = inner_match.group(1).split(',')[0].strip()
                    sym_matches = re.findall(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\b', inner_txt)
                    reserved = {'sin', 'cos', 'tan', 'exp', 'log', 'ln', 'sqrt', 'pi', 'I', 'E', 'abs', 'diff', 'int'}
                    cand_syms = [s for s in sym_matches if s not in reserved and not s.isdigit()]
                    if cand_syms:
                        var_name = cand_syms[0]

            if var_name:
                if isinstance(raw_val, list):
                    if len(raw_val) == 1:
                        val_str = str(raw_val[0])
                        val_ltx = sp.latex(raw_val[0]) if isinstance(raw_val[0], sp.Basic) else str(raw_val[0])
                        formatted_res.exact_text = f"{var_name} = {val_str}"
                        formatted_res.exact_latex = f"{var_name} = {val_ltx}"
                        formatted_res.numeric_text = f"{var_name} = {val_str}"
                        formatted_res.numeric_latex = f"{var_name} = {val_ltx}"
                    elif len(raw_val) > 1:
                        items_txt = [f"{var_name} = {v}" for v in raw_val]
                        items_ltx = [f"{var_name} = {sp.latex(v) if isinstance(v, sp.Basic) else str(v)}" for v in raw_val]
                        formatted_res.exact_text = ", ".join(items_txt)
                        formatted_res.exact_latex = r"\left\{ " + ",~ ".join(items_ltx) + r" \right\}"
                elif isinstance(raw_val, (int, float, sp.Number)):
                    formatted_res.exact_text = f"{var_name} = {raw_val}"
                    formatted_res.exact_latex = f"{var_name} = {sp.latex(raw_val) if isinstance(raw_val, sp.Basic) else str(raw_val)}"
                elif isinstance(raw_val, dict):
                    items_txt = [f"{k} = {v}" for k, v in raw_val.items()]
                    items_ltx = [f"{sp.latex(k) if isinstance(k, sp.Basic) else str(k)} = {sp.latex(v) if isinstance(v, sp.Basic) else str(v)}" for k, v in raw_val.items()]
                    formatted_res.exact_text = "{" + ", ".join(items_txt) + "}"
                    formatted_res.exact_latex = r"\left\{ " + ",~ ".join(items_ltx) + r" \right\}"

        self._update_history(exec_idx, raw_val, formatted_res)
        return formatted_res

    def _update_history(self, idx: int, raw_val, res: CASResult):
        """Update history variables: ans, _, _1, Out[1], and ditto operators %, %%, %%%."""
        self.history[idx] = res
        self.history_raw[idx] = raw_val
        # Update ditto / ans history
        self.namespace['_ans_3'] = self.namespace.get('_ans_2', raw_val)
        self.namespace['_ans_2'] = self.namespace.get('ans', raw_val)
        self.namespace['ans'] = raw_val
        self.namespace['_'] = raw_val
        self.namespace[f'_{idx}'] = raw_val
        self.namespace[f'Out_{idx}'] = raw_val

cas_engine/formatter.py:
"""
Result formatter for CAS Engine.
Converts SymPy objects and calculations into:
- Standard typeset LaTeX (for Matplotlib mathtext / rendering)
- Evaluated numeric floats (with precision control)
- Pretty plain text
- Copyable Python / CAS expressions
"""

import re
import sympy as sp
import numpy as np


class CASResult:
    """Encapsulates the result of a CAS calculation."""
    def __init__(self, raw_result, exact_latex: str, numeric_latex: str,
                 exact_text: str, numeric_text: str, python_code: str,
                 is_numeric_available: bool = True, is_plot: bool = False,
                 plot_data: dict = None, result_type: str = "Symbolic",
                 execution_time_ms: float = 0.0, suppress_output: bool = False):
        self.raw_result = raw_result
        self.exact_latex = exact_latex
        self.numeric_latex = numeric_latex
        self.exact_text = exact_text
        self.numeric_text = numeric_text
        self.python_code = python_code
        self.is_numeric_available = is_numeric_available
        self.is_plot = is_plot
        self.plot_data = plot_data or {}
        self.result_type = result_type
        self.execution_time_ms = execution_time_ms
        self.suppress_output = suppress_output


class MathFormatter:
    """
    Handles formatting of SymPy expressions into LaTeX, text, and numeric representations.
    Supports customizable decimal separator (comma ',' by default per user request, or period '.').
    """

    decimal_separator: str = ','

    @classmethod
    def set_decimal_separator(cls, sep: str):
        """Set the active decimal separator (',' or '.')."""
        if sep in (',', '.'):
            cls.decimal_separator = sep

    @classmethod
    def format_decimal(cls, text: str, sep: str = None) -> str:
        """Replace decimal points in plain text with the active decimal separator."""
        if sep is None:
            sep = cls.decimal_separator
        if sep == ',':
            return re.sub(r'(?<=\d)\.(?=\d)', ',', text)
        elif sep == '.':
            return re.sub(r'(?<=\d),(?=\d)', '.', text)
        return text

    @classmethod
    def format_latex_decimal(cls, latex_str: str, sep: str = None) -> str:
        """
        Format decimal numbers in LaTeX.
        In LaTeX math mode, a decimal comma must be written as {,} to avoid unwanted punctuation spacing.
        """
        if sep is None:
            sep = cls.decimal_separator
        if sep == ',':
            return re.sub(r'(?<=\d)\.(?=\d)', '{,}', latex_str)
        elif sep == '.':
            # Remove LaTeX decimal comma grouping if switching back to period
            return re.sub(r'(?<=\d)\{,\}(?=\d)', '.', latex_str)
        return latex_str

    @classmethod
    def clean_latex_for_mathtext(cls, latex_str: str) -> str:
        r"""
        Adjust SymPy LaTeX output to be 100% compatible with Matplotlib mathtext engine.
        For instance, convert \begin{bmatrix} -> \left[\begin{matrix}...\end{matrix}\right],
        remove unsupported \displaystyle, and ensure spacing/font commands are mathtext safe.
        """
        s = latex_str.strip()
        # Remove \displaystyle which is not supported in mathtext
        s = s.replace(r'\displaystyle', '')
        # Mathtext supports \begin{matrix} with \left[ and \right]
        s = s.replace(r'\begin{bmatrix}', r'\left[\begin{matrix}')
        s = s.replace(r'\end{bmatrix}', r'\end{matrix}\right]')
        s = s.replace(r'\begin{pmatrix}', r'\left(\begin{matrix}')
        s = s.replace(r'\end{pmatrix}', r'\end{matrix}\right)')
        s = s.replace(r'\begin{vmatrix}', r'\left|\begin{matrix}')
        s = s.replace(r'\end{vmatrix}', r'\end{matrix}\right|')
        s = s.replace(r'\operatorname{', r'\mathrm{')
        s = s.replace(r'\text{', r'\mathrm{')
        # Convert custom set and logic functions in LaTeX
        s = re.sub(r'\\(?:mathrm|operatorname)\{Intersection\}\s*\{?\s*(?:\\left\(|\()\s*(.*?)\s*,\s*(.*?)\s*(?:\\right\)|\))\s*\}?', lambda m: f'{m.group(1)} \\cap {m.group(2)}', s)
        s = re.sub(r'\\(?:mathrm|operatorname)\{Union\}\s*\{?\s*(?:\\left\(|\()\s*(.*?)\s*,\s*(.*?)\s*(?:\\right\)|\))\s*\}?', lambda m: f'{m.group(1)} \\cup {m.group(2)}', s)
        s = re.sub(r'\\(?:mathrm|operatorname)\{Subset\}\s*\{?\s*(?:\\left\(|\()\s*(.*?)\s*,\s*(.*?)\s*(?:\\right\)|\))\s*\}?', lambda m: f'{m.group(1)} \\subset {m.group(2)}', s)
        s = re.sub(r'\\(?:mathrm|operatorname)\{Superset\}\s*\{?\s*(?:\\left\(|\()\s*(.*?)\s*,\s*(.*?)\s*(?:\\right\)|\))\s*\}?', lambda m: f'{m.group(1)} \\supset {m.group(2)}', s)
        s = re.sub(r'\\(?:mathrm|operatorname)\{Contains\}\s*\{?\s*(?:\\left\(|\()\s*(.*?)\s*,\s*(.*?)\s*(?:\\right\)|\))\s*\}?', lambda m: f'{m.group(1)} \\in {m.group(2)}', s)
        s = re.sub(r'\\(?:mathrm|operatorname)\{Exists\}\s*\{?\s*(?:\\left\(|\()\s*(.*?)\s*,\s*(.*?)\s*(?:\\right\)|\))\s*\}?', lambda m: f'\\exists {m.group(1)} : {m.group(2)}', s)
        s = re.sub(r'\\(?:mathrm|operatorname)\{ForAll\}\s*\{?\s*(?:\\left\(|\()\s*(.*?)\s*,\s*(.*?)\s*(?:\\right\)|\))\s*\}?', lambda m: f'\\forall {m.group(1)} : {m.group(2)}', s)
        return s.strip()

    @classmethod
    def to_latex(cls, expr) -> str:
        """Generate formatted LaTeX string from SymPy expression or Python structure."""
        if expr is None:
            return ""
        try:
            if isinstance(expr, (list, tuple)):
                items = [sp.latex(item) if hasattr(item, 'is_symbol') or isinstance(item, (sp.Basic, sp.MatrixBase, sp.Eq)) else str(item) for item in expr]
                raw_latex = r"\left[ " + ",~ ".join(items) + r" \right]"
                res = cls.clean_latex_for_mathtext(raw_latex)
            elif isinstance(expr, dict):
                res = cls.format_dict(expr, is_latex=True)
            elif isinstance(expr, set):
                items = [cls.to_latex(item) for item in expr]
                raw_latex = r"\left\{ " + ",~ ".join(items) + r" \right\}"
                res = cls.clean_latex_for_mathtext(raw_latex)
            elif hasattr(expr, '_repr_latex_'):
                raw_latex = expr._repr_latex_().strip('$')
                res = cls.clean_latex_for_mathtext(raw_latex)
            elif isinstance(expr, (sp.Basic, sp.MatrixBase, sp.Eq)):
                raw_latex = sp.latex(expr)
                res = cls.clean_latex_for_mathtext(raw_latex)
            elif isinstance(expr, (int, float, complex, np.number)):
                res = str(expr)
            elif isinstance(expr, str):
                if re.match(r'^0b[01\s]+$', expr):
                    res = expr.replace(' ', r'\ ')
                elif re.match(r'^0x[0-9a-fA-F\s]+$', expr):
                    res = expr.replace(' ', r'\ ')
                else:
                    try:
                        res = sp.latex(sp.sympify(expr))
                    except Exception:
                        res = str(expr)
            else:
                res = sp.latex(sp.sympify(expr))
        except Exception:
            res = str(expr)
        return cls.format_latex_decimal(res)

    @classmethod
    def to_numeric(cls, expr, precision: int = 6):
        """
        Evaluate expression numerically (to float / complex float / numeric matrix).
        """
        if expr is None:
            return None
        try:
            if isinstance(expr, (int, float, complex, np.number)):
                if isinstance(expr, float):
                    return round(expr, precision)
                return expr
            elif isinstance(expr, sp.MatrixBase):
                return expr.evalf(precision)
            elif isinstance(expr, (list, tuple)):
                return [cls.to_numeric(x, precision) for x in expr]
            elif isinstance(expr, dict):
                return {cls.to_numeric(k, precision): cls.to_numeric(v, precision) for k, v in expr.items()}
            elif isinstance(expr, sp.Eq):
                return sp.Eq(cls.to_numeric(expr.lhs, precision), cls.to_numeric(expr.rhs, precision))
            elif isinstance(expr, (sp.Basic, sp.Expr)):
                evaluated = expr.evalf(precision)
                return evaluated
            else:
                sym_expr = sp.sympify(expr)
                return sym_expr.evalf(precision)
        except Exception:
            return expr

    @classmethod
    def to_numeric_str(cls, expr, precision: int = 6) -> str:
        """Generate numeric string for display."""
        num_val = cls.to_numeric(expr, precision)
        if num_val is None:
            return ""
        if isinstance(num_val, sp.MatrixBase):
            s = str(num_val)
        else:
            s = str(num_val)
        return cls.format_decimal(s)

    @classmethod
    def get_result_type(cls, expr) -> str:
        """Determine human-readable result type."""
        if expr is None:
            return "None"
        if isinstance(expr, sp.MatrixBase):
            return f"Matrix ({expr.rows}×{expr.cols})"
        if isinstance(expr, sp.Eq):
            return "Equation"
        if isinstance(expr, dict):
            return "Embedded Record" if any('hex' in str(k) or 'baud' in str(k) or 'timer' in str(k) or 'adc' in str(k) or 'q_' in str(k) or 'ieee' in str(k) or 'cutoff' in str(k) or 'crc' in str(k) or 'comp' in str(k) for k in expr.keys()) else f"Record ({len(expr)} fields)"
        if isinstance(expr, (list, tuple, set)):
            return f"List / Set ({len(expr)} items)"
        if isinstance(expr, (int, float, sp.Integer, sp.Float, sp.Rational)):
            return "Number"
        if isinstance(expr, sp.Derivative):
            return "Derivative"
        if isinstance(expr, sp.Integral):
            return "Integral"
        from sympy.core.relational import Relational
        if isinstance(expr, Relational):
            return "Inequality"
        if isinstance(expr, sp.Symbol):
            return "Symbol"
        if isinstance(expr, sp.Expr):
            return "Expression"
        return type(expr).__name__

    @classmethod
    def format_dict(cls, d: dict, is_latex: bool = False, precision: int = 4) -> str:
        """Format dictionary / embedded record cleanly with engineering units and rounded numbers."""
        if not d:
            return r"\left[ \right]" if is_latex else "[]"

        sep = cls.decimal_separator

        # 1. Specialized cleaner for rc_cutoff
        if "cutoff_frequency_hz" in d and ("time_constant_tau_ms" in d or "time_constant_tau_sec" in d):
            fc = float(d.get("cutoff_frequency_hz", 0.0))
            tau_sec = float(d.get("time_constant_tau_sec", 0.0))
            if tau_sec == 0.0 and "time_constant_tau_ms" in d:
                tau_sec = float(d.get("time_constant_tau_ms", 0.0)) / 1000.0

            # Auto SI units for fc
            if fc >= 1e9:
                fc_val, fc_unit = f"{fc/1e9:.3g}", "GHz"
            elif fc >= 1e6:
                fc_val, fc_unit = f"{fc/1e6:.3g}", "MHz"
            elif fc >= 1e3:
                fc_val, fc_unit = f"{fc/1e3:.3g}", "kHz"
            else:
                fc_val, fc_unit = f"{fc:.2f}".rstrip("0").rstrip("."), "Hz"

            # Auto SI units for tau
            if tau_sec >= 1.0:
                tau_val, tau_unit = f"{tau_sec:.3g}", "s"
            elif tau_sec >= 1e-3:
                tau_val, tau_unit = f"{tau_sec*1e3:.3g}", "ms"
            elif tau_sec >= 1e-6:
                tau_val, tau_unit = f"{tau_sec*1e6:.3g}", "µs"
            else:
                tau_val, tau_unit = f"{tau_sec*1e9:.3g}", "ns"

            # Settle time (5*tau)
            settle_sec = tau_sec * 5.0
            if settle_sec >= 1.0:
                set_val, set_unit = f"{settle_sec:.3g}", "s"
            elif settle_sec >= 1e-3:
                set_val, set_unit = f"{settle_sec*1e3:.3g}", "ms"
            elif settle_sec >= 1e-6:
                set_val, set_unit = f"{settle_sec*1e6:.3g}", "µs"
            else:
                set_val, set_unit = f"{settle_sec*1e9:.3g}", "ns"

            fc_val = cls.format_decimal(fc_val, sep)
            tau_val = cls.format_decimal(tau_val, sep)
            set_val = cls.format_decimal(set_val, sep)

            if is_latex:
                return (
                    rf"\left[\begin{{matrix}} "
                    rf"\mathbf{{Cutoff~Frequency}}: & {fc_val}~\mathrm{{{fc_unit}}} \\ "
                    rf"\mathbf{{Time~Constant~(\tau)}}: & {tau_val}~\mathrm{{{tau_unit}}} \\ "
                    rf"\mathbf{{Settle~Time~(99\%)}}: & {set_val}~\mathrm{{{set_unit}}} "
                    rf"\end{{matrix}}\right]"
                )
            else:
                return f"[Cutoff = {fc_val} {fc_unit}, Tau (τ) = {tau_val} {tau_unit}, Settle (99%) = {set_val} {set_unit}]"

        # 2. General dictionary formatting
        UNIT_SUFFIXES = {
            "_hz": "Hz", "_khz": "kHz", "_mhz": "MHz", "_ghz": "GHz",
            "_sec": "s", "_s": "s", "_ms": "ms", "_us": "µs", "_ns": "ns",
            "_ohms": "Ω", "_ohm": "Ω", "_kohms": "kΩ", "_kohm": "kΩ", "_mohms": "MΩ", "_mohm": "MΩ",
            "_v": "V", "_mv": "mV", "_kv": "kV",
            "_a": "A", "_ma": "mA", "_ua": "µA",
            "_w": "W", "_mw": "mW",
            "_pct": "%", "_percent": "%",
            "_db": "dB",
            "_bytes": "bytes", "_bits": "bits"
        }

        entries = []
        latex_rows = []
        for k, v in d.items():
            k_str = str(k)
            unit = ""
            for sfx, u in UNIT_SUFFIXES.items():
                if k_str.lower().endswith(sfx):
                    unit = u
                    k_str = k_str[:-len(sfx)]
                    break

            clean_k = k_str.replace("_", " ").strip().title()
            if not clean_k:
                clean_k = str(k)

            if isinstance(v, float):
                if abs(v - round(v)) < 1e-9:
                    v_str = str(int(round(v)))
                elif abs(v) >= 1e4 or (abs(v) < 1e-3 and abs(v) > 0):
                    v_str = f"{v:.4g}"
                else:
                    v_str = f"{v:.4f}".rstrip("0").rstrip(".")
                v_str = cls.format_decimal(v_str, sep)
                val_disp = f"{v_str} {unit}".strip() if unit else v_str
            elif isinstance(v, int):
                val_disp = f"{v} {unit}".strip() if unit else str(v)
            else:
                val_disp = str(v)

            entries.append(f"{clean_k} = {val_disp}")
            if is_latex:
                k_latex = clean_k.replace(" ", "~")
                val_latex = cls.format_latex_decimal(val_disp, sep)
                latex_rows.append(rf"\mathbf{{{k_latex}}}: & \mathrm{{{val_latex}}}")

        if is_latex:
            return r"\left[\begin{matrix} " + r" \\ ".join(latex_rows) + r" \end{matrix}\right]"
        else:
            return "[" + ",  ".join(entries) + "]"

    @classmethod
    def format_all(cls, raw_result, execution_time_ms: float = 0.0, precision: int = 6, suppress_output: bool = False) -> CASResult:
        """
        Produce a full CASResult bundle containing exact and numeric LaTeX/text representations.
        """
        if isinstance(raw_result, dict):
            exact_latex = cls.format_dict(raw_result, is_latex=True, precision=precision)
            exact_text = cls.format_dict(raw_result, is_latex=False, precision=precision)
            numeric_latex = exact_latex
            numeric_text = exact_text
            is_numeric_available = True
        else:
            # Exact LaTeX & Text
            exact_latex = cls.format_latex_decimal(cls.to_latex(raw_result))
            exact_text = sp.pretty(raw_result) if isinstance(raw_result, (sp.Basic, sp.MatrixBase)) else str(raw_result)
            exact_text = re.sub(r'\bIntersection\((.*?), (.*?)\)', r'\1 ∩ \2', exact_text)
            exact_text = re.sub(r'\bUnion\((.*?), (.*?)\)', r'\1 ∪ \2', exact_text)
            exact_text = re.sub(r'\bSubset\((.*?), (.*?)\)', r'\1 ⊂ \2', exact_text)
            exact_text = re.sub(r'\bSuperset\((.*?), (.*?)\)', r'\1 ⊃ \2', exact_text)
            exact_text = re.sub(r'\bContains\((.*?), (.*?)\)', r'\1 ∈ \2', exact_text)
            exact_text = cls.format_decimal(exact_text)

            # Numeric Evaluation
            try:
                numeric_obj = cls.to_numeric(raw_result, precision)
                numeric_latex = cls.format_latex_decimal(cls.to_latex(numeric_obj))
                numeric_text = sp.pretty(numeric_obj) if isinstance(numeric_obj, (sp.Basic, sp.MatrixBase)) else str(numeric_obj)
                numeric_text = cls.format_decimal(numeric_text)
                is_numeric_available = True
            except Exception:
                numeric_latex = exact_latex
                numeric_text = exact_text
                is_numeric_available = False

        # Python Code
        try:
            if isinstance(raw_result, (sp.Basic, sp.MatrixBase)):
                python_code = str(raw_result)
            else:
                python_code = repr(raw_result)
        except Exception:
            python_code = str(raw_result)

        result_type = cls.get_result_type(raw_result)

        return CASResult(
            raw_result=raw_result,
            exact_latex=exact_latex,
            numeric_latex=numeric_latex,
            exact_text=exact_text,
            numeric_text=numeric_text,
            python_code=python_code,
            is_numeric_available=is_numeric_available,
            is_plot=False,
            result_type=result_type,
            execution_time_ms=execution_time_ms,
            suppress_output=suppress_output
        )

