LAYOUT_WORDS = {
    'true', 'false', 'normal', 'center', '2D~Input', '2D~Output', 'italic',
    'unset', 'placeholder', 'baseline', 'axis', 'right', 'left', 'none',
    'auto', 'ColVector', 'RowVector', 'Matrix', 'Times~New~Roman', 'bold'
